mapper.select:
SELECT 
FROM EDU_COURSE_MANAGER C
WHERE C.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND C.ACTIVITY = '1'

    AND C.TRAIN_TYPE_CODE IN (
        SELECT S.TRAIN_TYPE_CODE FROM EDU_SYSTEM_MANAGER S
        WHERE S.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
          AND S.TRAIN_DIFF_CODE = #{trainDiffCode, jdbcType=VARCHAR}
    )


    AND C.TRAIN_TYPE_CODE = #{trainTypeCode, jdbcType=VARCHAR}


    AND UPPER(C.COURSE_NAME_CODE) LIKE '%' || UPPER(#{courseName, jdbcType=VARCHAR}) || '%'

ORDER BY C.CREATE_DATE DESC

SELECT 
FROM EDU_COURSE_MANAGER C
WHERE C.COURSE_NO = #{courseNo, jdbcType=VARCHAR}
  AND C.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

SELECT MAX(COURSE_NUMBER)
FROM EDU_COURSE_MANAGER
WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND ACTIVITY = '1'
  AND TRAIN_TYPE_CODE = #{trainTypeCode, jdbcType=VARCHAR}

mapper.update:
UPDATE EDU_COURSE_MANAGER
   SET COURSE_NAME_CODE = #{courseNameCode, jdbcType=VARCHAR},
       REMARK = #{remark, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE COURSE_NO = #{courseNo, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

UPDATE EDU_PLAN_MANAGER
   SET COURSE_NAME_CODE = #{courseNameCode, jdbcType=VARCHAR}
 WHERE COURSE_NO = #{courseNo, jdbcType=NUMERIC}

UPDATE EDU_BASIC_INFORMATION B
   SET B.COURSE_NAME_CODE = #{courseNameCode, jdbcType=VARCHAR}
 WHERE B.PLAN_NO IN (SELECT P.PLAN_NO FROM EDU_PLAN_MANAGER P WHERE P.COURSE_NO = #{courseNo, jdbcType=NUMERIC})
